question:
What is the output of reading?
File.WriteAllText("test.txt", "ABC");
string content = File.ReadAllText("test.txt");
Console.WriteLine(content.Length);

What does File.Delete() do?
File.WriteAllText("temp.txt", "Data");
File.Delete("temp.txt");
Console.WriteLine(File.Exists("temp.txt"));

What does StreamWriter do?
using (var writer = new StreamWriter("test.txt")) {
  writer.WriteLine("Line 1");
}

What does StreamReader do?
using (var reader = new StreamReader("test.txt")) {
  string line = reader.ReadLine();
}

What does File.ReadAllLines() return?
File.WriteAllText("test.txt", "A\nB\nC");
string[] lines = File.ReadAllLines("test.txt");
Console.WriteLine(lines.Length);

What does Directory.CreateDirectory() do?
Directory.CreateDirectory("folder");
Console.WriteLine(Directory.Exists("folder"));

What does File.Copy() do?
File.WriteAllText("source.txt", "Data");
File.Copy("source.txt", "dest.txt");
Console.WriteLine(File.Exists("dest.txt"));
